VALUES ('5e92b82e-af95-4105-b225-013452f24d35', '英検料金', 'exact', 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","spacing":"sm","backgroundColor":"#FFF5F9","contents":[{"type":"text","text":"あいことば｜英検®のご案内","size":"xs","wrap":true,"color":"#B07A9A"},{"type":"text","text":"第3回 英検®の日程・検定料","size":"lg","wrap":true,"color":"#5B3350","weight":"bold"},{"type":"text","text":"一次 1月23日（土）北島中央校\n5級　11:20〜　2,400円\n4級　13:00〜　2,800円\n3級　14:40〜　4,900円\n準2級　17:00〜　6,000円\n2級　19:15〜　6,800円","size":"sm","wrap":true,"color":"#4A4048"},{"type":"text","text":"二次 3月7日（日）\n12月15日（火）に検定料＋事務手数料100円を引き落とします。","size":"sm","wrap":true,"color":"#4A4048"}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","backgroundColor":"#FFFFFF","contents":[{"type":"button","style":"secondary","color":"#F6D3E3","height":"sm","action":{"type":"message","label":"級を選んで申し込む","text":"英検申込"},"margin":"sm"},{"type":"button","style":"secondary","color":"#EEE7EC","height":"sm","action":{"type":"message","label":"申込状況を確認する","text":"英検申込確認"},"margin":"sm"}]}}', NULL, '0797696f-e377-4132-bb17-77bc1db29b0a', 1)
