VALUES ('91d80313-35e2-497e-ad65-d8277c88e0b5', '英検申込確認', 'exact', 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","spacing":"sm","backgroundColor":"#FFF5F9","contents":[{"type":"text","text":"あいことば｜英検®のご案内","size":"xs","wrap":true,"color":"#B07A9A"},{"type":"text","text":"お申し込みの確認","size":"lg","wrap":true,"color":"#5B3350","weight":"bold"},{"type":"text","text":"「承認待ち」は教室で確認中です。確定したら、このトークでお知らせします。12月4日（金）までは、確定後も下のボタンからキャンセルできます。","size":"sm","wrap":true,"color":"#4A4048"}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","backgroundColor":"#FFFFFF","contents":[{"type":"button","style":"secondary","color":"#F6D3E3","height":"sm","action":{"type":"uri","label":"申込状況の確認・キャンセル","uri":"https://liff.line.me/2010714049-6L0KFjN7/?page=event-me"},"margin":"sm"},{"type":"button","style":"secondary","color":"#EEE7EC","height":"sm","action":{"type":"message","label":"級を選んで申し込む","text":"英検申込"},"margin":"sm"}]}}', NULL, '0797696f-e377-4132-bb17-77bc1db29b0a', 1)
