INSERT INTO auto_replies (id, keyword, match_type, response_type, response_content, template_id, line_account_id, is_active)
VALUES ('ae1796fe-8a83-48dc-8706-ca6157ef8ecb', '英検アプリ', 'exact', 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","spacing":"sm","backgroundColor":"#FFF5F9","contents":[{"type":"text","text":"あいことば｜英検®のご案内","size":"xs","wrap":true,"color":"#B07A9A"},{"type":"text","text":"ReadPass × AudiPass で、英検®学習の新体験","size":"lg","wrap":true,"color":"#5B3350","weight":"bold"},{"type":"text","text":"ECCベストワンの冬期講習を受講すると、リーディングの「ReadPass」とリスニングの「AudiPass」が使えます。","size":"sm","wrap":true,"color":"#4A4048"},{"type":"text","text":"📖 長文も 🎧 リスニングも、級ごとの形式で。スマホやタブレットで、自分のペースで続けられます。","size":"sm","wrap":true,"color":"#4A4048"},{"type":"text","text":"✍️ 画面で解くだけで終わらないのが特長です。書き込み式のワークが充実し、個別指導と連携した宿題で、教室とおうちの学習をつなげます。","size":"sm","wrap":true,"color":"#4A4048"},{"type":"text","text":"体験版は登録不要で、各級1回分をお試しいただけます。","size":"sm","wrap":true,"color":"#4A4048"},{"type":"text","text":"※英検®は、公益財団法人 日本英語検定協会の登録商標です。このコンテンツは、公益財団法人 日本英語検定協会の承認や推奨、その他の検討を受けたものではありません。","size":"xxs","wrap":true,"color":"#8A7F88"}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","backgroundColor":"#FFFFFF","contents":[{"type":"button","style":"secondary","color":"#F6D3E3","height":"sm","action":{"type":"uri","label":"体験版を試す（登録不要）","uri":"https://trial-for-read-pass-audi-pass.vercel.app/"},"margin":"sm"},{"type":"button","style":"secondary","color":"#F6D3E3","height":"sm","action":{"type":"uri","label":"冬期講習のご案内を見る","uri":"https://bestone-tokushima-winter-2026.vercel.app/"},"margin":"sm"},{"type":"button","style":"secondary","color":"#EEE7EC","height":"sm","action":{"type":"message","label":"英検®の申込に戻る","text":"英検申込"},"margin":"sm"}]}}', NULL, '0797696f-e377-4132-bb17-77bc1db29b0a', 1)
